class Q2LightState:  # q2-night-light
    # What the printer screen shows on its light button: the user's choice, not the lamp itself.
    def __init__(self, pin):
        self.pin = pin
    def get_status(self, eventtime):
        p = self.pin
        if p.q2_night:
            return {'value': 0.}
        return {'value': p.outputpin.last_value if p.outputpin else 0.}

