    def execute_logic(self):
        logging.info("加载了灯箱光的智能管理")
        self.is_enabled = 1
        self.printer.register_event_handler("ui:sleep", self._handle_ui_event)
        # q2-night-light: light switched off by hand during a print = night mode for this print
        self.q2_night = False
        self.q2_peek = False
        self.q2_ai_timer = None
        self.q2_ai_off = False
        self.printer.add_object('q2_light_state', Q2LightState(self))
    def execute_logic(self):
        logging.info("加载了灯箱光的智能管理")
        self.is_enabled = 1
        # q2-night-light: watch SET_PIN PIN=caselight (screen button, LED_ON/LED_OFF, Fluidd)
        key, values = self.gcode.mux_commands['SET_PIN']
        self.q2_orig_set_pin = values[self.short_name]
        values[self.short_name] = self._q2_cmd_set_pin

    def _q2_cmd_set_pin(self, gcmd):
        self.q2_orig_set_pin(gcmd)
        try:
            on = gcmd.get_float('VALUE', 0.) > 0.
            ps = self.printer.lookup_object('print_stats', None)
            if ps is None or ps.state not in ('printing', 'paused'):
                return
            if not on and not self.q2_night:
                self._q2_cancel_timer()
                self.q2_night = True
                self.q2_peek = False
                self.is_active = False
                self._q2_ai(False)
                if self._q2_ai_set():
                    self.gcode.respond_info("Dark mode: light and spaghetti detection are OFF until the print ends. Tap the printer's screen to turn the light on temporarily, turn the light switch on to restore.")
                else:
                    self.gcode.respond_info("Dark mode: light is OFF until the print ends. Tap the printer's screen to turn the light on temporarily, turn the light switch on to restore.")
            elif not on:
                self.q2_peek = False
            elif self.q2_night:
                self.q2_night = False
                self.q2_peek = False
                self.is_active = True
                self._q2_cancel_timer()
                reactor = self.printer.get_reactor()
                self.q2_ai_timer = reactor.register_timer(self._q2_ai_back, reactor.monotonic() + 60.)
                self.gcode.respond_info("Dark mode ended: light ON, spaghetti detection back in 60 s." if self._q2_ai_set() else "Dark mode ended: light ON.")
        except Exception:
            logging.exception("q2-night-light: SET_PIN hook")

    def _q2_cancel_timer(self):
        if self.q2_ai_timer is not None:
            self.printer.get_reactor().unregister_timer(self.q2_ai_timer)
            self.q2_ai_timer = None

    def _q2_ai_back(self, eventtime):
        self.q2_ai_timer = None
        if not self.q2_night:
            self._q2_ai(True)
            if self._q2_ai_set():
                self.gcode.respond_info("Spaghetti detection is back ON.")
        return self.printer.get_reactor().NEVER

    def _q2_ai_set(self):
        return bool(int(self.save_variables.allVariables.get('enable_noodle_detection', 0)))

    def _q2_ai(self, on):
        # only the in-memory switch of this print; the saved setting is never changed
        ai = self.printer.lookup_object('ai_func_manager', None)
        if ai is None or (on and not self.q2_ai_off):
            return
        self.q2_ai_off = not on
        for cfg in ai.ai_configs.values():
            if cfg.get('save_key') == 'enable_noodle_detection':
                cfg['enabled'] = int(self.save_variables.allVariables.get('enable_noodle_detection', 0)) if on else 0

